package ro.hsldigitallab.casamia.receiver;

import org.json.JSONObject;
import java.io.*;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import javax.net.ssl.HttpsURLConnection;

final class ApiClient {
    static final class Failure extends IOException {
        final int status;
        Failure(int status, String text) { super(text); this.status = status; }
    }
    static JSONObject call(String base, String token, String route, JSONObject body, String key) throws Exception {
        URL url = new URL(ReceiverRules.baseUrl(base) + "api/index.php?path=" + route);
        HttpsURLConnection c = (HttpsURLConnection) url.openConnection();
        c.setInstanceFollowRedirects(false); c.setConnectTimeout(6000); c.setReadTimeout(8000);
        c.setRequestProperty("Accept", "application/json"); c.setRequestProperty("Cache-Control", "no-store");
        if (!token.isEmpty()) c.setRequestProperty("Authorization", "Bearer " + token);
        if (key != null) c.setRequestProperty("Idempotency-Key", key);
        try {
            if (body != null) {
                byte[] bytes = body.toString().getBytes(StandardCharsets.UTF_8);
                c.setRequestMethod("POST"); c.setDoOutput(true);
                c.setRequestProperty("Content-Type", "application/json; charset=utf-8"); c.setFixedLengthStreamingMode(bytes.length);
                try (OutputStream out = c.getOutputStream()) { out.write(bytes); }
            }
            int status = c.getResponseCode();
            InputStream stream = status >= 200 && status < 300 ? c.getInputStream() : c.getErrorStream();
            if (stream == null) throw new Failure(status, "Serverul nu a confirmat cererea.");
            byte[] bytes;
            try (InputStream in = stream; ByteArrayOutputStream out = new ByteArrayOutputStream()) {
                byte[] b = new byte[4096]; int n;
                while ((n = in.read(b)) != -1) { if (out.size() + n > 1024 * 1024) throw new IOException("Răspuns prea mare."); out.write(b, 0, n); }
                bytes = out.toByteArray();
            }
            JSONObject result;
            try { result = new JSONObject(new String(bytes, StandardCharsets.UTF_8)); }
            catch (Exception e) { throw new Failure(status, "Adresa nu răspunde cu API-ul Casa Mia. Verifică instalarea pe găzduire."); }
            if (status < 200 || status >= 300) throw new Failure(status,
                    result.optString("error", "Cererea nu a fost confirmată (" + status + ")."));
            return result;
        } finally { c.disconnect(); }
    }
}

package ro.hsldigitallab.casamia.receiver;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.media.AudioManager;
import android.os.*;
import android.provider.Settings;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.text.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

public final class MainActivity extends Activity {
    private static final int NAVY=0xff111c23,CREAM=0xfff6f1e7,GOLD=0xffdfc38a,INK=0xff263238,MUTED=0xff6d736f;
    private final ExecutorService network=Executors.newSingleThreadExecutor();
    private final Handler main=new Handler(Looper.getMainLooper());
    private SecureStore store;
    private LinearLayout body,nav,orderList;
    private ScrollView scroll;
    private TextView receiverBadge;
    private EditText searchInput;
    private String tab="orders",statusFilter="all",search="",reportPeriod="day",renderKey="";
    private boolean pairing;
    private OrderAlarm preview;
    private final Runnable refresh=this::render;
    private final Runnable clock=new Runnable(){@Override public void run(){render();main.postDelayed(this,5000);}};
    @Override public void onCreate(Bundle state){
        super.onCreate(state);store=new SecureStore(this);getWindow().setStatusBarColor(NAVY);getWindow().setNavigationBarColor(NAVY);setVolumeControlStream(AudioManager.STREAM_ALARM);
        LinearLayout root=column();root.setBackgroundColor(CREAM);root.setFocusableInTouchMode(true);root.requestFocus();setContentView(root);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
        root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        LinearLayout header=column();header.setPadding(dp(22),dp(15),dp(22),dp(15));header.setBackgroundColor(NAVY);
        TextView brand=text("Casa Mia  by OAna",28,GOLD);brand.setTypeface(Typeface.create("serif",Typeface.NORMAL));header.addView(brand);
        receiverBadge=text("",12,CREAM);receiverBadge.setPadding(0,dp(7),0,0);header.addView(receiverBadge);receiverBadge.setOnClickListener(v->{tab="orders";statusFilter="înregistrată";renderKey="";render();scroll.smoothScrollTo(0,0);});root.addView(header);
        nav=new LinearLayout(this);nav.setPadding(dp(12),dp(10),dp(12),dp(8));root.addView(nav);
        scroll=new ScrollView(this);scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=column();body.setPadding(dp(18),dp(10),dp(18),dp(26));scroll.addView(body);
        loadView(false);render();
    }
    @Override protected void onStart(){super.onStart();ReceiverState.listener=refresh;render();}
    @Override protected void onResume(){super.onResume();main.post(clock);}
    @Override protected void onPause(){main.removeCallbacks(clock);if(preview!=null){preview.close();preview=null;}super.onPause();}
    @Override protected void onStop(){if(ReceiverState.listener==refresh)ReceiverState.listener=null;super.onStop();}
    @Override protected void onDestroy(){network.shutdownNow();super.onDestroy();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(2),1.02f);return t;}
    private TextView heading(String s,int size){TextView t=text(s,size,INK);t.setTypeface(Typeface.create("serif",Typeface.NORMAL));return t;}
    private GradientDrawable surface(int color,int radius,int border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(border!=0)d.setStroke(dp(1),border);return d;}
    private void gap(LinearLayout into,int n){into.addView(new View(this),new LinearLayout.LayoutParams(1,dp(n)));}
    private Button button(String label,boolean primary,View.OnClickListener listener){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setTextColor(INK);b.setMinHeight(dp(48));b.setPadding(dp(12),dp(8),dp(12),dp(8));b.setBackground(surface(primary?GOLD:0xfffbf8f1,12,primary?0:0xffded6c7));b.setOnClickListener(listener);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);b.setLayoutParams(p);return b;}
    private String money(long cents){return new DecimalFormat("#,##0.##",DecimalFormatSymbols.getInstance(new Locale("ro","RO"))).format(cents/100.0)+" lei";}
    private String when(String raw){if(raw==null||raw.isEmpty()||raw.equals("null"))return "—";try{return Instant.parse(raw.contains("T")?raw:raw.replace(' ','T')+"Z").atZone(Metrics.ZONE).format(DateTimeFormatter.ofPattern("dd.MM.yyyy · HH:mm:ss"));}catch(Exception e){return raw;}}
    private String label(JSONObject o){return o.optInt("dailyNumber")>0?"#"+String.format(Locale.ROOT,"%03d",o.optInt("dailyNumber")):"#"+o.optString("id","------").substring(0,6).toUpperCase(Locale.ROOT);}
    private String stateLabel(String state){switch(state){case "înregistrată":return "De preluat";case "în preparare":return "Acceptată · în preparare";case "gata":return "Gata de predare";case "finalizată":return "Finalizată";case "anulată":return "Anulată";default:return state;}}
    private int stateColor(String state){switch(state){case "înregistrată":return 0xffa04432;case "în preparare":return 0xff8b682e;case "gata":return 0xff326b56;default:return MUTED;}}
    private void chips(LinearLayout into,String[] labels,String[] values,String selected,java.util.function.Consumer<String> action){HorizontalScrollView horizontal=new HorizontalScrollView(this);horizontal.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);horizontal.addView(row);for(int i=0;i<labels.length;i++){final String value=values[i];Button b=button(labels[i],value.equals(selected),v->action.accept(value));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.rightMargin=dp(7);row.addView(b,p);}into.addView(horizontal);gap(into,10);}
    private void render(){
        if(body==null||isFinishing()||isDestroyed())return;
        receiverBadge.setText((ReceiverState.demo?"DEMONSTRAȚIE":"RESTAURANT")+"  ·  "+(ReceiverState.running?(ReceiverState.online?"Recepție activă":"Conexiune de verificat"):"Recepție oprită")+"  ·  "+ReceiverState.pending+" de preluat");
        if(ReceiverState.pending>0&&preview!=null){preview.close();preview=null;}
        String key=tab+statusFilter+ReceiverState.date+ReceiverState.period+reportPeriod+ReceiverState.running+ReceiverState.demo+ReceiverState.busy+ReceiverState.history.toString()+ReceiverState.orders.toString()+ReceiverState.insights.toString()+ReceiverState.message+ReceiverState.historyMessage+(System.currentTimeMillis()/30000);
        if(key.equals(renderKey))return;renderKey=key;int y=scroll.getScrollY();boolean typing=searchInput!=null&&searchInput.hasFocus();int caret=typing?searchInput.getSelectionStart():0;
        nav.removeAllViews();String[] tabs={"orders","reports","settings"},names={"Comenzi","Rapoarte","Setări"};
        for(int i=0;i<tabs.length;i++){final String choice=tabs[i];Button b=button(names[i],tab.equals(choice),v->{hideKeyboard();tab=choice;scroll.scrollTo(0,0);renderKey="";render();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(46),1);p.setMargins(dp(3),0,dp(3),0);nav.addView(b,p);}
        body.removeAllViews();searchInput=null;
        if(tab.equals("settings"))settings();else{dateControls();if(tab.equals("reports"))reports();else orders();}
        if(typing&&searchInput!=null){searchInput.requestFocus();searchInput.setSelection(Math.min(Math.max(0,caret),searchInput.length()));}
        scroll.post(()->scroll.scrollTo(0,y));
    }
    private void hideKeyboard(){View focus=getCurrentFocus();if(focus!=null){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(focus.getWindowToken(),0);focus.clearFocus();}nav.setFocusableInTouchMode(true);nav.requestFocus();}
    private void dateControls(){
        Button date=button("◷  "+LocalDate.parse(ReceiverState.date).format(DateTimeFormatter.ofPattern("dd MMMM yyyy",new Locale("ro","RO")))+"  ·  alege data",false,v->{LocalDate d=LocalDate.parse(ReceiverState.date);DatePickerDialog picker=new DatePickerDialog(this,(a,year,month,day)->changeView(LocalDate.of(year,month+1,day).toString(),ReceiverState.period),d.getYear(),d.getMonthValue()-1,d.getDayOfMonth());picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();});body.addView(date);
        if(!ReceiverState.date.equals(Metrics.today()))body.addView(button("Revino la ziua de azi",false,v->changeView(Metrics.today(),ReceiverState.period)));
        if(!ReceiverState.historyMessage.isEmpty()){body.addView(text(ReceiverState.historyMessage,13,0xffa04432));gap(body,10);}
    }
    private void changeView(String date,String period){ReceiverState.date=date;ReceiverState.period=period;ReceiverState.followToday=Metrics.today().equals(date);ReceiverState.history=new JSONArray();ReceiverState.nextCursor="";ReceiverState.historyExhausted=false;loadView(false);renderKey="";render();}
    private void loadView(boolean more){
        if(ReceiverState.running){Intent i=new Intent(this,ReceiverService.class).setAction(more?ReceiverService.MORE:ReceiverService.VIEW).putExtra("date",ReceiverState.date).putExtra("period",ReceiverState.period);startService(i);return;}
        network.execute(()->{try{
            ReceiverState.demo=Boolean.parseBoolean(store.get("demo","true"));
            if(ReceiverState.demo){OrderBook book=new OrderBook(store);ReceiverState.history=book.history(ReceiverState.date,ReceiverState.period);ReceiverState.insights=book.insights(ReceiverState.date);}
            else{JSONObject c=new JSONObject(store.get("connection","{}"));if(!c.optString("token").isEmpty()){
                JSONObject page=ApiClient.call(c.getString("base"),c.getString("token"),"device/history&date="+ReceiverState.date+"&period="+ReceiverState.period+(more?"&cursor="+ReceiverState.nextCursor:""),null,null);
                if(!more)ReceiverState.history=page.getJSONArray("orders");else{JSONArray combined=new JSONArray(ReceiverState.history.toString());JSONArray extra=page.getJSONArray("orders");for(int n=0;n<extra.length();n++)combined.put(extra.getJSONObject(n));ReceiverState.history=combined;}
                ReceiverState.nextCursor=page.isNull("nextCursor")?"":page.getString("nextCursor");ReceiverState.historyExhausted=ReceiverState.nextCursor.isEmpty();ReceiverState.insights=ApiClient.call(c.getString("base"),c.getString("token"),"device/insights&date="+ReceiverState.date,null,null);
            }}ReceiverState.historyMessage="";
        }catch(Exception e){ReceiverState.historyMessage="Istoricul nu s-a actualizat. "+e.getMessage();}finally{main.post(()->{renderKey="";render();});}});
    }
    private void orders(){
        body.addView(text(ReceiverState.message,13,MUTED));gap(body,10);
        if(!ReceiverState.running){body.addView(button("Testează o comandă",true,v->startShift(true)));try{if(!new JSONObject(store.get("connection","{}")).optString("token").isEmpty())body.addView(button("Începe tura · comenzi reale",true,v->startShift(false)));}catch(Exception ignored){}}
        else if(ReceiverState.demo)body.addView(button("+ Comandă de test în 5 secunde",true,v->action(ReceiverService.ADD_DEMO)));
        chips(body,new String[]{"Zi","Săptămână","Lună","Tot istoricul"},new String[]{"day","week","month","all"},ReceiverState.period,p->changeView(ReceiverState.date,p));
        JSONObject daily=ReceiverState.insights.optJSONObject("day");if(daily!=null){body.addView(text(daily.optInt("received")+" comenzi în ziua selectată  ·  "+daily.optInt("completed")+" finalizate",13,MUTED));gap(body,10);}
        chips(body,new String[]{"Toate","De preluat","În preparare","Gata","Finalizate","Anulate"},new String[]{"all","înregistrată","în preparare","gata","finalizată","anulată"},statusFilter,f->{statusFilter=f;renderKey="";render();});
        searchInput=new EditText(this);searchInput.setSingleLine(true);searchInput.setTextSize(15);searchInput.setHint("Caută nr., preparat sau client");searchInput.setText(search);body.addView(searchInput);gap(body,12);
        orderList=column();body.addView(orderList);searchInput.addTextChangedListener(new TextWatcher(){@Override public void beforeTextChanged(CharSequence s,int a,int c,int f){}@Override public void onTextChanged(CharSequence s,int a,int b,int c){search=s.toString();renderOrderList();}@Override public void afterTextChanged(Editable e){}});renderOrderList();
        if(!ReceiverState.nextCursor.isEmpty())body.addView(button("Încarcă următoarele comenzi",false,v->loadView(true)));
        if(ReceiverState.demo){gap(body,12);body.addView(text("DATE DEMONSTRATIVE · comenzile și rapoartele de aici sunt fictive și rămân separate de restaurant.",12,MUTED));}
    }
    private void renderOrderList(){
        if(orderList==null)return;orderList.removeAllViews();Map<String,JSONObject> unique=new LinkedHashMap<>();
        try{for(int i=0;i<ReceiverState.orders.length();i++){JSONObject o=ReceiverState.orders.getJSONObject(i);unique.put(o.getString("id"),o);}for(int i=0;i<ReceiverState.history.length();i++){JSONObject o=ReceiverState.history.getJSONObject(i);if(!unique.containsKey(o.getString("id")))unique.put(o.getString("id"),o);}}catch(JSONException ignored){}
        List<JSONObject> rows=new ArrayList<>(unique.values());rows.sort((a,b)->{int sa=priority(a.optString("status")),sb=priority(b.optString("status"));if(sa!=sb)return Integer.compare(sa,sb);int d=b.optString("businessDay").compareTo(a.optString("businessDay"));return d!=0?d:Integer.compare(b.optInt("dailyNumber"),a.optInt("dailyNumber"));});
        int shown=0;for(JSONObject o:rows){if(!statusFilter.equals("all")&&!statusFilter.equals(o.optString("status")))continue;String hay=(label(o)+" "+o.optInt("dailyNumber")+" "+o.optString("name")+" "+o.optString("phone")+" "+o.optString("items")).toLowerCase(new Locale("ro","RO"));if(!search.trim().isEmpty()&&!hay.contains(search.toLowerCase(new Locale("ro","RO")).trim()))continue;orderCard(o);shown++;}
        if(shown==0)orderList.addView(text("Nicio comandă pentru selecția curentă. Comenzile noi vor apărea aici când recepția este pornită.",15,MUTED));
    }
    private int priority(String s){switch(s){case "înregistrată":return 0;case "în preparare":return 1;case "gata":return 2;case "finalizată":return 3;default:return 4;}}
    private void orderCard(JSONObject o){
        LinearLayout card=column();card.setPadding(dp(16),dp(14),dp(16),dp(14));String state=o.optString("status");card.setBackground(surface(state.equals("înregistrată")?0xffffeee3:0xfffffdf8,15,state.equals("înregistrată")?0xffd5a587:0xffe2d9c9));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);orderList.addView(card,p);
        card.addView(text(label(o)+"  ·  "+stateLabel(state),15,stateColor(state)));gap(card,5);
        card.addView(text((o.optString("mode").equals("livrare")?"Livrare":"Ridicare")+"  ·  "+when(o.optString("createdAt")),12,MUTED));
        JSONArray items=o.optJSONArray("items");StringBuilder dishes=new StringBuilder();if(items!=null)for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(i>0)dishes.append(" · ");dishes.append(item.optInt("quantity")).append(" × ").append(item.optString("name"));}gap(card,7);card.addView(text(dishes.toString(),16,INK));gap(card,6);
        String notes=o.optString("notes");if(!notes.isEmpty())card.addView(text("Observații client · apasă pentru detalii",12,0xff947746));
        card.addView(text(money(o.optLong("total"))+"  ·  "+o.optString("name"),14,INK));
        if(state.equals("înregistrată")){try{long seconds=Duration.between(Instant.parse(o.getString("createdAt")),Instant.now()).getSeconds();card.addView(text("Așteaptă de "+Math.max(0,seconds/60)+" min",12,stateColor(state)));}catch(Exception ignored){}}
        card.setOnClickListener(v->openOrder(o));card.setFocusable(true);card.setContentDescription("Deschide comanda "+label(o)+", "+stateLabel(state));
    }
    private void reports(){
        body.addView(heading("Privire de ansamblu.",29));gap(body,8);body.addView(text("Informații care ajută tura de azi și deciziile de mâine.",14,MUTED));gap(body,15);
        chips(body,new String[]{"Zi","Săptămână","Lună"},new String[]{"day","week","month"},reportPeriod,p->{reportPeriod=p;renderKey="";render();});
        JSONObject r=ReceiverState.insights.optJSONObject(reportPeriod);if(r==null){body.addView(text("Rapoartele apar după prima sincronizare sau după adăugarea comenzilor de test.",15,MUTED));return;}
        metricPair("Comenzi primite",Integer.toString(r.optInt("received")),"Confirmate",Integer.toString(r.optInt("confirmed")));
        metricPair("Valoare confirmată",money(r.optLong("value")),"Valoare medie",money(r.optLong("average")));
        body.addView(text(r.optInt("completed")+" finalizate  ·  "+r.optInt("cancelled")+" anulate  ·  "+r.optInt("pending")+" nepreluate",13,MUTED));gap(body,18);
        JSONObject largest=r.optJSONObject("largest");LinearLayout max=column();max.setPadding(dp(18),dp(16),dp(18),dp(16));max.setBackground(surface(NAVY,16,0));max.addView(text("CEA MAI MARE COMANDĂ CONFIRMATĂ",11,GOLD));gap(max,8);max.addView(text(largest==null?"Nicio comandă confirmată":money(largest.optLong("total")),27,CREAM));if(largest!=null){max.addView(text(label(largest)+" · "+largest.optString("businessDay"),14,CREAM));max.setOnClickListener(v->findOrder(largest.optString("id")));}body.addView(max);gap(body,20);
        body.addView(heading("Preparatele preferate",23));gap(body,10);JSONArray top=r.optJSONArray("topDishes");if(top==null||top.length()==0)body.addView(text("Clasamentul apare după confirmarea comenzilor.",14,MUTED));else for(int i=0;i<top.length();i++){JSONObject d=top.optJSONObject(i);body.addView(text((i+1)+". "+d.optString("name"),16,INK));body.addView(text(d.optInt("quantity")+" porții · "+money(d.optLong("value")),13,MUTED));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(top.optJSONObject(0).optInt("quantity",1));bar.setProgress(d.optInt("quantity"));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xffb38e4f));body.addView(bar,new LinearLayout.LayoutParams(-1,dp(8)));gap(body,13);}
        gap(body,10);body.addView(text("Valoarea și media includ ambalajul și livrarea și exclud comenzile anulate sau neacceptate. Topul preparatelor numără porțiile confirmate. Aceste valori reprezintă comenzi, fără a certifica încasarea sau profitul. Săptămâna începe luni; orele sunt ale României.",12,MUTED));
        if(ReceiverState.demo){gap(body,18);body.addView(button("Exemple pentru rapoarte · 28 zile",false,v->{if(!ReceiverState.running){Toast.makeText(this,"Pornește mai întâi testul de recepție.",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Adaugi exemple fictive?").setMessage("Adaugă o singură dată exemple din ultimele 28 de zile. Nu creează comenzi reale și nu pornesc alarme pentru istoricul demonstrativ.").setNegativeButton("Înapoi",null).setPositiveButton("Adaugă exemple",(d,w)->action(ReceiverService.SEED)).show();}));}
    }
    private void metricPair(String a,String av,String b,String bv){LinearLayout row=new LinearLayout(this);String[] names={a,b},values={av,bv};for(int i=0;i<2;i++){LinearLayout card=column();card.setPadding(dp(13),dp(16),dp(13),dp(16));card.setBackground(surface(0xfffffdf8,15,0xffe2d9c9));card.addView(text(names[i],12,MUTED));gap(card,7);card.addView(text(values[i],22,INK));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,0,i==0?dp(10):0,dp(10));row.addView(card,p);}body.addView(row);}
    private void findOrder(String id){try{for(int i=0;i<ReceiverState.history.length();i++){JSONObject o=ReceiverState.history.getJSONObject(i);if(id.equals(o.getString("id"))){openOrder(o);return;}}}catch(JSONException ignored){}if(!ReceiverState.demo)fetchOrder(id);else{try{details(new OrderBook(store).get(id));}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}}
    private void openOrder(JSONObject o){if(!ReceiverState.demo&&!o.optBoolean("archived"))fetchOrder(o.optString("id"));else details(o);}
    private void fetchOrder(String id){Toast.makeText(this,"Actualizez detaliile comenzii…",Toast.LENGTH_SHORT).show();network.execute(()->{try{JSONObject c=new JSONObject(store.get("connection","{}"));JSONObject order=ApiClient.call(c.getString("base"),c.getString("token"),"device/order&orderId="+id,null,null);ReceiverService.mergeHistory(order);main.post(()->{details(order);renderKey="";render();});}catch(Exception e){main.post(()->Toast.makeText(this,"Nu am putut actualiza detaliile: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}
    private void details(JSONObject o){
