        AlertDialog d = new AlertDialog.Builder(this).setTitle("Conectează restaurantul").setView(form).setNegativeButton("Înapoi", null).setPositiveButton("Conectează", null).create();
        d.setOnShowListener(ignored -> d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v -> {
            try {
                String base = ReceiverRules.baseUrl(url.getText().toString());
                String pairingCode = code.getText().toString().trim().toUpperCase(Locale.ROOT).replace("-", "").replace(" ", "");
                if (!pairingCode.matches("[A-Z2-9]{10}")) throw new IllegalArgumentException("Introdu codul temporar de 10 caractere.");
                pairing = true; d.dismiss(); ReceiverState.message = "Conectez telefonul în siguranță…"; render();
                network.execute(() -> {
                    try {
                        JSONObject response = ApiClient.call(base, "", "device/pair", new JSONObject().put("code", pairingCode), null);
                        String token = response.getString("token"); if (!token.matches("[a-f0-9]{64}")) throw new IllegalStateException("Credential primit într-un format invalid.");
                        String deviceId = response.getString("deviceId"); long expires = response.getLong("tokenExpiresAt");
                        if (!deviceId.matches("[a-f0-9]{32}") || expires <= System.currentTimeMillis() / 1000) throw new IllegalStateException("Conectarea primită este invalidă sau expirată.");
                        // One encrypted commit: never combine an old token with a newly entered server URL.
                        store.put("connection", new JSONObject().put("base", base).put("token", token).put("deviceId", deviceId).put("expires", expires).toString());
                        ReceiverState.pending = 0; ReceiverState.orders = new JSONArray(); ReceiverState.history = new JSONArray(); ReceiverState.insights = new JSONObject(); ReceiverState.accepted = "";
                        ReceiverState.message = "Telefon conectat. Apasă Începe tura pentru a primi comenzile reale.";
                    } catch (Exception e) { ReceiverState.message = e.getMessage() == null ? "Conectarea nu a reușit. Verifică adresa și codul." : e.getMessage(); }
                    finally { pairing = false; main.post(this::render); }
                });
            } catch (IllegalArgumentException e) { Toast.makeText(this, e.getMessage(), Toast.LENGTH_LONG).show(); }
        })); d.show();
    }
}

package ro.hsldigitallab.casamia.receiver;

import java.time.*;
import java.util.*;

/** Money is always integer bani. Confirmed value is not a statement of payment or profit. */
final class Metrics {
    static final ZoneId ZONE = ZoneId.of("Europe/Bucharest");
    static final class Line {
        final String id, name; final int price, quantity;
        Line(String id, String name, int price, int quantity) { this.id=id;this.name=name;this.price=price;this.quantity=quantity; }
    }
    static final class Order {
        final String id, day, status; final int number, total; final List<Line> items;
        Order(String id,String day,String status,int number,int total,List<Line> items){this.id=id;this.day=day;this.status=status;this.number=number;this.total=total;this.items=items;}
    }
    static final class Top { String id,name; int quantity; long value; }
    static final class Result {
        int received,cancelled,pending,confirmed,completed; long value,average; Order largest; List<Top> top = new ArrayList<>();
    }
    static String today() { return LocalDate.now(ZONE).toString(); }
    static String day(String instant) { return Instant.parse(instant).atZone(ZONE).toLocalDate().toString(); }
    static LocalDate from(String date,String period) {
        LocalDate d=LocalDate.parse(date);
        switch(period){case "day":return d;case "week":return d.minusDays(d.getDayOfWeek().getValue()-1);case "month":return d.withDayOfMonth(1);case "all":return LocalDate.MIN;default:throw new IllegalArgumentException("Perioadă invalidă.");}
    }
    static boolean contains(String day,String anchor,String period) {
        LocalDate d=LocalDate.parse(day), start=from(anchor,period), end;
        switch(period){case "week":end=start.plusDays(7);break;case "month":end=start.plusMonths(1);break;default:end=LocalDate.parse(anchor).plusDays(1);}
        return !d.isBefore(start)&&d.isBefore(end);
    }
    static boolean confirmed(String status) { return Arrays.asList("acceptată","în preparare","gata","finalizată").contains(status); }
    static Result calculate(List<Order> orders,String date,String period) {
        Result r=new Result();Map<String,Top> top=new HashMap<>();
        for(Order o:orders){if(!contains(o.day,date,period))continue;r.received++;
            if(o.status.equals("anulată"))r.cancelled++;
            if(o.status.equals("înregistrată"))r.pending++;
            if(o.status.equals("finalizată"))r.completed++;
            if(!confirmed(o.status))continue;r.confirmed++;r.value+=o.total;
            if(r.largest==null||o.total>r.largest.total)r.largest=o;
            for(Line line:o.items){Top t=top.get(line.id);if(t==null){t=new Top();t.id=line.id;t.name=line.name;top.put(line.id,t);}t.quantity+=line.quantity;t.value+=(long)line.price*line.quantity;}
        }
        r.average=r.confirmed==0?0:Math.round((double)r.value/r.confirmed);
        r.top.addAll(top.values());r.top.sort(Comparator.comparingInt((Top t)->-t.quantity).thenComparingLong(t->-t.value).thenComparing(t->t.id));
        return r;
    }
}

package ro.hsldigitallab.casamia.receiver;

import android.app.NotificationManager;
import android.content.Context;
import android.media.*;
import android.os.*;

/** Own repeating audio, separate from a dismissible system notification. Never overrides calls or DND. */
final class OrderAlarm {
    private final Context context;
    private final AudioManager audio;
    private final Vibrator vibrator;
    private final Handler main = new Handler(Looper.getMainLooper());
    private MediaPlayer player;
    private AudioFocusRequest focus;
    private boolean focused, desired, vibrating, closed;
    private volatile boolean playbackFailed;
    private long focusRetryAt;
    private int playingProfile=-1;
    OrderAlarm(Context c) {
        context = c; audio = c.getSystemService(AudioManager.class); vibrator = c.getSystemService(Vibrator.class);
    }
    static boolean ready(Context c) {
        AudioManager a = c.getSystemService(AudioManager.class);
        int filter = c.getSystemService(NotificationManager.class).getCurrentInterruptionFilter();
        return a.getStreamVolume(AudioManager.STREAM_ALARM) > 0
                && (filter == NotificationManager.INTERRUPTION_FILTER_ALL || filter == NotificationManager.INTERRUPTION_FILTER_ALARMS);
    }
    boolean isReady() { return !playbackFailed && ready(context); }
    void update(boolean needed) { main.post(() -> { if (!closed) { desired = needed; reconcile(); } }); }
    private void reconcile() {
        int mode = audio.getMode();
        if (!desired || !ready(context) || mode == AudioManager.MODE_IN_CALL || mode == AudioManager.MODE_IN_COMMUNICATION
                || mode == AudioManager.MODE_RINGTONE) {
            silence();
            if (!desired) { if (focus != null) audio.abandonAudioFocusRequest(focus); focus = null; focused = false; }
            return;
        }
        if (!focused) {
            if (SystemClock.elapsedRealtime() < focusRetryAt) return;
            if (focus == null) focus = new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT)
                    .setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM)
                            .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build())
                    .setWillPauseWhenDucked(true)
                    .setOnAudioFocusChangeListener(change -> {
                        focused = change == AudioManager.AUDIOFOCUS_GAIN;
                        if (!focused) { focusRetryAt = SystemClock.elapsedRealtime() + 10000; silence(); }
                        else reconcile();
                    }, main).build();
            focused = audio.requestAudioFocus(focus) == AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
            if (!focused) { focusRetryAt = SystemClock.elapsedRealtime() + 10000; return; }
        }
        try {
            int selected=SoundProfile.selected(context);
            if(player!=null&&playingProfile!=selected)silence();
            if (player == null) {
                player = new MediaPlayer();
                player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM)
                        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());
                try (android.content.res.AssetFileDescriptor afd = context.getResources().openRawResourceFd(SoundProfile.RES[selected])) {
                    player.setDataSource(afd.getFileDescriptor(), afd.getStartOffset(), afd.getLength());
                }
                player.setLooping(true); player.setVolume(1f,1f); player.prepare(); playingProfile=selected;
            }
            if (!player.isPlaying()) player.start();
            if (!vibrating && vibrator != null && vibrator.hasVibrator()) {
                vibrator.vibrate(VibrationEffect.createWaveform(new long[]{0, 180, 120, 180, 2600}, 0)); vibrating = true;
            }
        } catch (Exception e) {
            playbackFailed = true; silence(); ReceiverState.message = "Soneria nu a pornit. Verifică sunetul și redeschide recepția.";
        }
    }
    private void silence() {
        if (player != null) { try { player.release(); } catch (Exception ignored) { } player = null; }
        if (vibrator != null) vibrator.cancel(); vibrating = false;
    }
    void close() { main.post(() -> { closed = true; desired = false; reconcile(); }); }
}

package ro.hsldigitallab.casamia.receiver;

import org.json.*;
import java.time.*;
import java.util.*;

/** Separate, encrypted demo book: no fake records are ever uploaded to the restaurant. */
final class OrderBook {
    private final SecureStore store;
    private JSONArray all = new JSONArray();
    private boolean seeded;
    OrderBook(SecureStore store) throws Exception {this.store=store;JSONObject saved=new JSONObject(store.get("demo-book-v2","{}"));all=saved.optJSONArray("orders");if(all==null)all=new JSONArray();seeded=saved.optBoolean("seeded");}
    private void save() throws Exception {store.put("demo-book-v2",new JSONObject().put("orders",all).put("seeded",seeded).toString());}
    JSONObject add(Instant created,String status,int variant) throws Exception {
        String day=created.atZone(Metrics.ZONE).toLocalDate().toString();int number=0;
        for(int i=0;i<all.length();i++){JSONObject o=all.getJSONObject(i);if(day.equals(o.optString("businessDay")))number=Math.max(number,o.optInt("dailyNumber"));}
        String[] names={"Casa Mia Golden Burger","Tagliolini ai Funghi Porcini","Bulz – bilă reinterpretată","Clătită tiramisu"};int[] prices={7500,5800,4500,3500};
        int index=Math.floorMod(variant,4),quantity=variant%3==1?2:1,subtotal=prices[index]*quantity;String mode=variant%2==1&&subtotal>=7000?"livrare":"ridicare";
        JSONObject item=new JSONObject().put("id","demo-"+index).put("name",names[index]).put("quantity",quantity).put("price",prices[index]);
        JSONObject o=new JSONObject().put("id",UUID.randomUUID().toString().replace("-",""))
                .put("businessDay",day).put("dailyNumber",number+1).put("createdAt",created.toString()).put("status",status)
                .put("mode",mode).put("name","Client demonstrativ").put("phone","TEST · fără apel")
                .put("address",mode.equals("livrare")?"Adresă fictivă pentru test, Bragadiru":"").put("payment","Numerar · TEST")
                .put("notes",variant%2==0?"Fără ceapă. Sosul separat.\nCOMANDĂ DE TEST · nu se prepară și nu se facturează.":"Observație demonstrativă: tacâmuri pentru două persoane.\nCOMANDĂ DE TEST · nu se prepară și nu se facturează.")
                .put("items",new JSONArray().put(item)).put("subtotal",subtotal).put("packaging",200).put("delivery",0).put("total",subtotal+200).put("demo",true);
        if(Metrics.confirmed(status))o.put("acceptedAt",created.plusSeconds(40).toString()).put("preparingAt",created.plusSeconds(40).toString());
        all.put(o);save();return o;
    }
    int size(){return all.length();}
    void seed() throws Exception {
        if(seeded)return;int variant=0;
        for(int days=1;days<=28;days++){
            Instant at=LocalDate.now(Metrics.ZONE).minusDays(days).atTime(12,15).atZone(Metrics.ZONE).toInstant();
            add(at,days%7==0?"anulată":"finalizată",variant++);if(days%2==0)add(at.plusSeconds(7200),"finalizată",variant++);
        }
        seeded=true;save();
    }
    JSONObject get(String id)throws JSONException{for(int i=0;i<all.length();i++)if(id.equals(all.getJSONObject(i).getString("id")))return all.getJSONObject(i);throw new IllegalArgumentException("Comanda nu a fost găsită.");}
    void accept(String id,Integer eta,boolean area)throws Exception{
        JSONObject o=get(id);ReceiverRules.acceptance(o.getString("mode"),area);
        if(!o.getString("status").equals("înregistrată"))throw new IllegalArgumentException("Comanda a fost deja preluată.");
        String now=Instant.now().toString();o.put("status","în preparare").put("acceptedAt",now).put("preparingAt",now).put("etaMinutes",eta==null?JSONObject.NULL:eta);save();
    }
    void progress(String id,String to)throws Exception{
        JSONObject o=get(id);String expected=to.equals("gata")?"în preparare":to.equals("finalizată")?"gata":"";
        if(!o.getString("status").equals(expected))throw new IllegalArgumentException("Această schimbare nu este disponibilă.");o.put("status",to);save();
    }
    JSONArray pending()throws JSONException{JSONArray a=new JSONArray();for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("status").equals("înregistrată"))a.put(all.getJSONObject(i));return a;}
    JSONArray history(String date,String period)throws JSONException{
        List<JSONObject> rows=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject o=all.getJSONObject(i);if(Metrics.contains(o.getString("businessDay"),date,period))rows.add(o);}
        rows.sort((a,b)->{int d=b.optString("businessDay").compareTo(a.optString("businessDay"));return d!=0?d:Integer.compare(b.optInt("dailyNumber"),a.optInt("dailyNumber"));});return new JSONArray(rows);
    }
    JSONObject insights(String date)throws JSONException{
        List<Metrics.Order> rows=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject o=all.getJSONObject(i);List<Metrics.Line> items=new ArrayList<>();JSONArray is=o.getJSONArray("items");for(int j=0;j<is.length();j++){JSONObject it=is.getJSONObject(j);items.add(new Metrics.Line(it.getString("id"),it.getString("name"),it.getInt("price"),it.getInt("quantity")));}rows.add(new Metrics.Order(o.getString("id"),o.getString("businessDay"),o.getString("status"),o.getInt("dailyNumber"),o.getInt("total"),items));}
        JSONObject result=new JSONObject();for(String period:new String[]{"day","week","month"}){
            Metrics.Result r=Metrics.calculate(rows,date,period);JSONObject value=new JSONObject().put("received",r.received).put("cancelled",r.cancelled).put("pending",r.pending).put("confirmed",r.confirmed).put("completed",r.completed).put("value",r.value).put("average",r.average);
            if(r.largest!=null)value.put("largest",new JSONObject().put("id",r.largest.id).put("dailyNumber",r.largest.number).put("businessDay",r.largest.day).put("total",r.largest.total));
            JSONArray top=new JSONArray();for(Metrics.Top t:r.top)top.put(new JSONObject().put("id",t.id).put("name",t.name).put("quantity",t.quantity).put("value",t.value));value.put("topDishes",top);result.put(period,value);
        }return result;
    }
}

package ro.hsldigitallab.casamia.receiver;

import java.net.URI;

/** Pure rules; an unavailable or invalid response must never clear a pending alarm. */
public final class ReceiverRules {
    private ReceiverRules() {}
    public static String baseUrl(String value) {
        try {
            URI u = new URI(value.trim());
            if (!"https".equalsIgnoreCase(u.getScheme()) || u.getHost() == null
                    || u.getUserInfo() != null || u.getQuery() != null || u.getFragment() != null
                    || (u.getPort() != -1 && u.getPort() != 443)
                    || u.getPath().contains("..")) throw new IllegalArgumentException();
            return u.toASCIIString().replaceAll("/+$", "") + "/";
        } catch (Exception e) { throw new IllegalArgumentException("Introdu adresa HTTPS a site-ului, fără coduri sau parametri."); }
    }
    public static int verifiedPending(int count, int loaded, boolean more, boolean alarm) {
        if (count < 0 || loaded < 0 || count < loaded || more != (count > loaded)
                || alarm != (count > 0) || (count > 0 && loaded == 0)) {
            throw new IllegalArgumentException("Răspuns incomplet. Alerta anterioară rămâne activă.");
        }
        return count;
    }
    public static Integer eta(String value) {
        if (value.trim().isEmpty()) return null;
        try { int n = Integer.parseInt(value.trim()); if (n >= 1 && n <= 240) return n; }
        catch (NumberFormatException ignored) { }
        throw new IllegalArgumentException("Estimarea trebuie să fie între 1 și 240 de minute.");
    }
    public static void acceptance(String mode, boolean areaVerified) {
        if ("livrare".equals(mode) && !areaVerified) {
            throw new IllegalArgumentException("Confirmă adresa în zona de livrare de 7 km.");
        }
    }
}

package ro.hsldigitallab.casamia.receiver;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.content.pm.ServiceInfo;
import android.os.*;
import org.json.*;
import java.util.UUID;
import java.util.concurrent.*;

public final class ReceiverService extends Service {
    static final String START_DEMO = "start-demo", START_REAL = "start-real", ADD_DEMO = "demo-add", ACCEPT = "accept", STOP = "stop", VIEW = "view", MORE = "more", SEED = "seed", PROGRESS = "progress";
    private static final String STATUS_CHANNEL = "reception-v1", ORDER_CHANNEL = "new-order-v1";
    private static final int STATUS_ID = 11, ORDER_ID = 12;
    private final ScheduledExecutorService worker = Executors.newSingleThreadScheduledExecutor();
    private SecureStore store;
    private OrderAlarm alarm;
    private PowerManager.WakeLock wake;
    private long heartbeatAt, wakeAt;
    private String base = "", token = "", deviceId = "";
    private long tokenExpiry;
    private volatile boolean ending;
    private OrderBook book;
    private long dashboardAt;
    private ScheduledFuture<?> loop;
    @Override public void onCreate() {
        super.onCreate(); store = new SecureStore(this); alarm = new OrderAlarm(this);
        NotificationManager nm = getSystemService(NotificationManager.class);
        NotificationChannel status = new NotificationChannel(STATUS_CHANNEL, "Recepție activă", NotificationManager.IMPORTANCE_LOW);
        status.setSound(null, null); nm.createNotificationChannel(status);
        NotificationChannel orders = new NotificationChannel(ORDER_CHANNEL, "Comenzi de preluat", NotificationManager.IMPORTANCE_HIGH);
        orders.setDescription("Alerta sonoră este repetată de aplicație până la acceptarea tuturor comenzilor.");
        orders.setSound(null, null); orders.enableVibration(false); nm.createNotificationChannel(orders);
        wake = getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, getPackageName() + ":reception");
        wake.setReferenceCounted(false);
    }
    @Override public int onStartCommand(Intent intent, int flags, int startId) {
        String action = intent == null ? "restore" : intent.getAction();
        if (STOP.equals(action)) {
            ending = true; ReceiverState.running = false;
            worker.execute(() -> { try { if (!ReceiverState.demo && !token.isEmpty()) heartbeat(false); store.put("active", "false"); }
                catch (Exception ignored) { } finally { stopSelf(); } });
            alarm.update(false); changed(); return START_NOT_STICKY;
        }
        // The foreground notification must exist before any storage or network work.
        Notification foreground = notification(STATUS_CHANNEL, "Casa Mia · recepție", "Pregătesc recepția comenzilor…", true);
        if (Build.VERSION.SDK_INT >= 34) startForeground(STATUS_ID, foreground, ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);
        else startForeground(STATUS_ID, foreground);
        worker.execute(() -> {
            try {
                if (!ReceiverState.running) {
                    if ("restore".equals(action) && !"true".equals(store.get("active", "false"))) { stopSelf(); return; }
                    ReceiverState.demo = START_DEMO.equals(action) || (!START_REAL.equals(action) && "true".equals(store.get("demo", "true")));
                    ReceiverState.orders = new JSONArray(); ReceiverState.pending = 0; ReceiverState.accepted = ""; ReceiverState.syncedAt = 0;
                    store.put("demo", Boolean.toString(ReceiverState.demo)); store.put("active", "true");
                    JSONObject connection = new JSONObject(store.get("connection", "{}"));
                    base = connection.optString("base"); token = connection.optString("token"); deviceId = connection.optString("deviceId"); tokenExpiry = connection.optLong("expires");
                    if (!ReceiverState.demo && (base.isEmpty() || !token.matches("[a-f0-9]{64}"))) throw new IllegalArgumentException("Conectează telefonul înainte de începerea turei.");
                    ReceiverState.history = new JSONArray(); ReceiverState.insights = new JSONObject();
                    book = new OrderBook(store);
                    String cached = ReceiverState.demo ? "" : store.get(snapshotKey(), "");
                    if (!cached.isEmpty()) applySync(new JSONObject(cached), false);
                    ReceiverState.running = true; ending = false;
                    ReceiverState.message = ReceiverState.demo ? "Mod demonstrativ · nicio comandă reală" : "Verific conexiunea cu restaurantul…";
                    if (loop == null) loop = worker.scheduleWithFixedDelay(this::tick, 0, 4, TimeUnit.SECONDS);
                }
                if (ADD_DEMO.equals(action) && ReceiverState.demo) {
                    ReceiverState.message = "Comanda de test apare în 5 secunde. Poți bloca ecranul.";
                    worker.schedule(() -> {try {if (!ending && ReceiverState.running && ReceiverState.demo) {demoOrder(); changed();}} catch (Exception e) {failure(e); changed();}},5,TimeUnit.SECONDS);
                }
                if (VIEW.equals(action) && intent != null) {
                    String date=intent.getStringExtra("date"),period=intent.getStringExtra("period");
                    Metrics.from(date,period); ReceiverState.date=date;ReceiverState.period=period;ReceiverState.followToday=Metrics.today().equals(date);
                    ReceiverState.history=new JSONArray();ReceiverState.nextCursor="";ReceiverState.historyExhausted=false;refreshDashboard(false);
                }
                if (MORE.equals(action)) refreshDashboard(true);
                if (SEED.equals(action) && ReceiverState.demo) {book.seed();refreshDashboard(false);}
                if (PROGRESS.equals(action) && intent != null) progress(intent.getStringExtra("orderId"),intent.getStringExtra("status"));
                if (ACCEPT.equals(action) && intent != null) accept(intent.getStringExtra("orderId"), intent.getStringExtra("eta"), intent.getBooleanExtra("area", false));
                changed();
            } catch (Exception e) { failure(e); if (!ReceiverState.running) { try { store.put("active", "false"); } catch (Exception ignored) { } stopSelf(); } }
        });
        return START_STICKY;
    }
    private void tick() {
        if (ending || !ReceiverState.running) return;
        try {
            long now = SystemClock.elapsedRealtime();
            if (now - wakeAt > 60000 || !wake.isHeld()) { wake.acquire(120000); wakeAt = now; }
            if (ReceiverState.demo) {
                ReceiverState.online = true;

            } else {
                if (now - heartbeatAt >= 20000 || heartbeatAt == 0) { heartbeat(true); heartbeatAt = now; }
                applySync(ApiClient.call(base, token, "device/sync", null, null), true);
                ReceiverState.online = true;
                ReceiverState.message = "Sincronizat cu restaurantul · recepție activă";
                if (tokenExpiry - System.currentTimeMillis() / 1000 < 3 * 86400) ReceiverState.message = "Accesul expiră în mai puțin de 3 zile. Reconectează telefonul din administrare.";
            }
            if (ReceiverState.followToday && !Metrics.today().equals(ReceiverState.date)) {ReceiverState.date=Metrics.today();ReceiverState.history=new JSONArray();dashboardAt=0;}
            if (ReceiverState.demo || now-dashboardAt>=8000 || dashboardAt==0) {refreshDashboard(false);dashboardAt=now;}
            if (!notificationsAllowed()) ReceiverState.message = "Notificările sunt oprite. Recepția reală nu este pregătită.";
            else if (!alarm.isReady()) ReceiverState.message = "Verifică volumul alarmelor și modul Nu deranja. Recepția reală nu este pregătită.";
        } catch (Exception e) { failure(e); }
        alarm.update(ReceiverState.pending > 0); changed();
    }
    private void heartbeat(boolean receiving) throws Exception {
        JSONObject flags = new JSONObject().put("receiving", receiving).put("notificationsAllowed", notificationsAllowed()).put("alarmReady", alarm.isReady());
        ApiClient.call(base, token, "device/heartbeat", flags, null);
    }
    private boolean notificationsAllowed() {
        NotificationManager nm = getSystemService(NotificationManager.class);
        return (Build.VERSION.SDK_INT < 33 || checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED)
                && nm.areNotificationsEnabled() && nm.getNotificationChannel(ORDER_CHANNEL).getImportance() != NotificationManager.IMPORTANCE_NONE;
    }
    private void applySync(JSONObject sync, boolean save) throws Exception {
        JSONArray orders = new JSONArray(sync.getJSONArray("orders").toString());
        int count = ReceiverRules.verifiedPending(sync.getInt("pendingCount"), orders.length(), sync.getBoolean("hasMore"), sync.getBoolean("alarmRequired"));
        for (int i = 0; i < orders.length(); i++) {
            JSONObject order = orders.getJSONObject(i);
            if (!order.getString("id").matches("[a-f0-9]{32}") || !"înregistrată".equals(order.getString("status"))) throw new IllegalArgumentException("Comandă primită într-un format invalid.");
        }
        if (save) store.put(snapshotKey(), sync.toString());
        ReceiverState.orders = orders; ReceiverState.pending = count;
        if (save) ReceiverState.syncedAt = System.currentTimeMillis();
        alarm.update(count > 0);
    }
    private String snapshotKey() { return ReceiverState.demo ? "demo-snapshot" : "snapshot-" + deviceId; }
    private JSONObject syncFor(JSONArray orders) throws JSONException {
        return new JSONObject().put("orders", orders).put("pendingCount", orders.length()).put("hasMore", false).put("alarmRequired", orders.length() > 0);
    }
    private void refreshDashboard(boolean more) {
        try {
            if(ReceiverState.demo){
                ReceiverState.history=new JSONArray(book.history(ReceiverState.date,ReceiverState.period).toString());ReceiverState.nextCursor="";
                ReceiverState.insights=book.insights(ReceiverState.date);applySync(syncFor(book.pending()),false);
            }else{
                String cursor=more?ReceiverState.nextCursor:"";
                if(more&&cursor.isEmpty())return;
                String route="device/history&date="+ReceiverState.date+"&period="+ReceiverState.period+(cursor.isEmpty()?"":"&cursor="+cursor);
                JSONObject page=ApiClient.call(base,token,route,null,null);
                JSONArray rows=page.getJSONArray("orders");
                java.util.LinkedHashMap<String,JSONObject> merged=new java.util.LinkedHashMap<>();
                // Fresh rows win. Older pages stay available during live refresh.
                for(int i=0;i<rows.length();i++)merged.put(rows.getJSONObject(i).getString("id"),rows.getJSONObject(i));
                for(int i=0;i<ReceiverState.history.length();i++){JSONObject o=ReceiverState.history.getJSONObject(i);if(!merged.containsKey(o.getString("id")))merged.put(o.getString("id"),o);}
                ReceiverState.history=new JSONArray(merged.values());
                if(more||(!ReceiverState.historyExhausted&&ReceiverState.nextCursor.isEmpty())){ReceiverState.nextCursor=page.isNull("nextCursor")?"":page.getString("nextCursor");ReceiverState.historyExhausted=ReceiverState.nextCursor.isEmpty();}
                ReceiverState.insights=ApiClient.call(base,token,"device/insights&date="+ReceiverState.date,null,null);
            }
            ReceiverState.historyMessage="";
        }catch(Exception e){ReceiverState.historyMessage="Istoricul nu s-a actualizat. "+(e.getMessage()==null?"Verifică instalarea backendului 0.2.":e.getMessage());}
    }
    private void demoOrder() throws Exception {
        book.add(java.time.Instant.now(),"înregistrată",book.size());refreshDashboard(false);
        ReceiverState.message="Comandă demonstrativă nouă · așteaptă acceptarea";
    }
    private void progress(String id,String to) throws Exception {
        ReceiverState.busy=true;changed();
        try{
            if(ReceiverState.demo)book.progress(id,to);
            else{
                JSONObject r=ApiClient.call(base,token,"device/status",new JSONObject().put("orderId",id).put("status",to),UUID.randomUUID().toString());
                if(!r.optBoolean("statusConfirmed")||!to.equals(r.optString("status")))throw new IllegalStateException("Serverul nu a confirmat statusul.");
                mergeHistory(r);
            }
            refreshDashboard(false);ReceiverState.message=to.equals("gata")?"Comanda este gata de predare.":"Comanda a fost finalizată.";
        }finally{ReceiverState.busy=false;changed();}
    }
    static void mergeHistory(JSONObject updated) throws JSONException {
        JSONArray rows=new JSONArray();boolean found=false;
        for(int i=0;i<ReceiverState.history.length();i++){JSONObject old=ReceiverState.history.getJSONObject(i);if(old.getString("id").equals(updated.getString("id"))){JSONObject combined=new JSONObject(old.toString());java.util.Iterator<String> keys=updated.keys();while(keys.hasNext()){String k=keys.next();combined.put(k,updated.get(k));}rows.put(combined);found=true;}else rows.put(old);}
        if(!found&&Metrics.contains(updated.optString("businessDay",Metrics.today()),ReceiverState.date,ReceiverState.period))rows.put(updated);
        ReceiverState.history=rows;
    }
    private void accept(String id, String etaText, boolean area) throws Exception {
        ReceiverState.busy = true; ReceiverState.message = "Confirm acceptarea…"; changed();
        try {
            JSONObject selected = null;
            for (int i = 0; i < ReceiverState.orders.length(); i++) if (ReceiverState.orders.getJSONObject(i).getString("id").equals(id)) selected = ReceiverState.orders.getJSONObject(i);
            if (selected == null) throw new IllegalArgumentException("Comanda nu mai este în lista curentă. Verifică sincronizarea.");
            Integer eta = ReceiverRules.eta(etaText == null ? "" : etaText); ReceiverRules.acceptance(selected.getString("mode"), area);
            if (ReceiverState.demo) {
                book.accept(id,eta,area);refreshDashboard(false);
            } else {
                String saved = store.get("accept-" + id, "");
                JSONObject request;
                if (saved.isEmpty()) {
                    JSONObject body = new JSONObject().put("orderId", id).put("etaMinutes", eta == null ? JSONObject.NULL : eta).put("deliveryAreaVerified", area);
                    request = new JSONObject().put("key", UUID.randomUUID().toString()).put("body", body);
                    store.put("accept-" + id, request.toString());
                } else request = new JSONObject(saved); // Same payload and idempotency key after a lost response.
                JSONObject confirmed = ApiClient.call(base, token, "device/accept", request.getJSONObject("body"), request.getString("key"));
                if (!confirmed.optBoolean("acceptanceConfirmed") || !"în preparare".equals(confirmed.optString("status")) || !id.equals(confirmed.optString("id"))) throw new IllegalStateException("Serverul nu a confirmat acceptarea. Alerta rămâne activă.");
                store.remove("accept-" + id);
                mergeHistory(confirmed);
                applySync(ApiClient.call(base, token, "device/sync", null, null), true);
            }
            refreshDashboard(false);
            ReceiverState.accepted = "Comanda #" + id.substring(0, 6).toUpperCase(java.util.Locale.ROOT) + " · acceptată, în preparare" + (ReceiverState.demo ? " (TEST)" : "");
            ReceiverState.message = ReceiverState.pending > 0 ? "Mai sunt " + ReceiverState.pending + " comenzi de preluat." : "Toate comenzile au fost preluate.";
        } catch (ApiClient.Failure e) {
            if (e.status == 409) { // Another staff member may have accepted it; only a valid sync can silence the alarm.
                applySync(ApiClient.call(base, token, "device/sync", null, null), true);
                boolean present = false;
                for (int i = 0; i < ReceiverState.orders.length(); i++) present |= id.equals(ReceiverState.orders.getJSONObject(i).getString("id"));
                if (!present) store.remove("accept-" + id);
            }
            throw e;
        } finally { ReceiverState.busy = false; alarm.update(ReceiverState.pending > 0); changed(); }
    }
    private void failure(Exception e) {
        ReceiverState.online = false;
        ReceiverState.message = e instanceof java.io.IOException && !(e instanceof ApiClient.Failure)
                ? "Conexiune întreruptă. Reîncerc automat; comenzile cunoscute rămân în așteptare."
                : (e.getMessage() == null ? "Recepția necesită verificare." : e.getMessage());
    }
    private Notification notification(String channel, String title, String text, boolean ongoing) {
        Intent open = new Intent(this, MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP | Intent.FLAG_ACTIVITY_CLEAR_TOP);
        PendingIntent tap = PendingIntent.getActivity(this, 0, open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
        return new Notification.Builder(this, channel).setSmallIcon(R.drawable.ic_order).setContentTitle(title).setContentText(text)
                .setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(tap).setOngoing(ongoing)
                .setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PRIVATE).setCategory(Notification.CATEGORY_EVENT).build();
    }
    private void changed() {
        NotificationManager nm = getSystemService(NotificationManager.class);
        if (Build.VERSION.SDK_INT < 33 || checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED) {
            if (ReceiverState.running) nm.notify(STATUS_ID, notification(STATUS_CHANNEL, "Casa Mia · " + (ReceiverState.demo ? "DEMONSTRAȚIE" : "recepție activă"), ReceiverState.message, true));
            if (ReceiverState.running && ReceiverState.pending > 0) nm.notify(ORDER_ID, notification(ORDER_CHANNEL, ReceiverState.pending + " comenzi de preluat", "Deschide Casa Mia și confirmă acceptarea. Alerta continuă până la preluare.", true));
            else nm.cancel(ORDER_ID);
        } else nm.cancel(ORDER_ID);
        ReceiverState.notifyChanged();
    }
    @Override public void onDestroy() {
        ending = true; ReceiverState.running = false; ReceiverState.online = false;
        worker.shutdownNow(); alarm.close(); if (wake != null && wake.isHeld()) wake.release();
        getSystemService(NotificationManager.class).cancel(ORDER_ID); changed(); super.onDestroy();
    }
    @Override public IBinder onBind(Intent intent) { return null; }
}

package ro.hsldigitallab.casamia.receiver;
import org.json.JSONArray;
import android.os.Handler;
import android.os.Looper;

final class ReceiverState {
    static volatile boolean running = false, demo = true, online = false, busy = false;
    static volatile int pending = 0;
    static volatile JSONArray orders = new JSONArray();
    static volatile boolean followToday = true, historyExhausted = false;
    static volatile JSONArray history = new JSONArray();
    static volatile org.json.JSONObject insights = new org.json.JSONObject();
    static volatile String date = Metrics.today(), period = "day", nextCursor = "";
    static volatile String historyMessage = "", soundName = "Casa Mia Signature";
    static volatile String message = "Testează recepția, apoi conectează restaurantul.", accepted = "";
    static volatile long syncedAt = 0;
    static volatile Runnable listener;
    private static final Handler main = new Handler(Looper.getMainLooper());
    static void notifyChanged() {
        Runnable callback = listener;
        if (callback != null) main.post(() -> { if (listener == callback) callback.run(); });
    }
    private ReceiverState() { }
}

package ro.hsldigitallab.casamia.receiver;

import android.content.Context;
import android.content.SharedPreferences;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.Base64;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;

/** Tokens, acceptance retries and the pending snapshot stay in encrypted, non-backed-up storage. */
final class SecureStore {
    private final SharedPreferences prefs;
    private static final String ALIAS = "casamia.receiver.v1";
    SecureStore(Context c) { prefs = c.getSharedPreferences("receiver_private", Context.MODE_PRIVATE); }
    private SecretKey key() throws Exception {
        KeyStore ks = KeyStore.getInstance("AndroidKeyStore"); ks.load(null);
        if (!ks.containsAlias(ALIAS)) {
            KeyGenerator g = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore");
            g.init(new KeyGenParameterSpec.Builder(ALIAS, KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());
            g.generateKey();
        }
        return (SecretKey) ks.getKey(ALIAS, null);
    }
    synchronized void put(String name, String value) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding"); cipher.init(Cipher.ENCRYPT_MODE, key());
        String stored = Base64.encodeToString(cipher.getIV(), Base64.NO_WRAP) + ":"
                + Base64.encodeToString(cipher.doFinal(value.getBytes(StandardCharsets.UTF_8)), Base64.NO_WRAP);
        if (!prefs.edit().putString(name, stored).commit()) throw new IllegalStateException("Nu am putut salva în siguranță pe telefon.");
    }
    synchronized String get(String name, String fallback) throws Exception {
        String saved = prefs.getString(name, null); if (saved == null) return fallback;
        String[] pair = saved.split(":", 2);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, key(), new GCMParameterSpec(128, Base64.decode(pair[0], Base64.NO_WRAP)));
        return new String(cipher.doFinal(Base64.decode(pair[1], Base64.NO_WRAP)), StandardCharsets.UTF_8);
    }
    synchronized void remove(String name) { prefs.edit().remove(name).commit(); }
}

