package ro.hsldigitallab.casamia.receiver;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class MetricsTest {
    private Metrics.Order order(String day,String status,int total,int qty){return new Metrics.Order("test",day,status,1,total,Collections.singletonList(new Metrics.Line("burger","Burger",7500,qty)));}
    @Test public void localMidnightAndDstAreCorrect(){assertEquals("2026-10-25",Metrics.day("2026-10-24T21:05:00Z"));assertEquals("2026-10-26",Metrics.day("2026-10-25T22:05:00Z"));}
    @Test public void weekStartsOnMonday(){assertTrue(Metrics.contains("2026-10-19","2026-10-25","week"));assertFalse(Metrics.contains("2026-10-26","2026-10-25","week"));}
    @Test public void monthDoesNotIncludeNeighbouringMonths(){assertTrue(Metrics.contains("2026-10-01","2026-10-25","month"));assertFalse(Metrics.contains("2026-09-30","2026-10-25","month"));assertFalse(Metrics.contains("2026-11-01","2026-10-25","month"));}
    @Test public void cancelledAndPendingDoNotInflateValue(){Metrics.Result r=Metrics.calculate(Arrays.asList(order("2026-10-25","finalizată",7700,1),order("2026-10-25","în preparare",15200,2),order("2026-10-25","anulată",75200,10),order("2026-10-25","înregistrată",75200,10)),"2026-10-25","day");assertEquals(4,r.received);assertEquals(2,r.confirmed);assertEquals(1,r.cancelled);assertEquals(1,r.pending);assertEquals(22900,r.value);assertEquals(11450,r.average);assertEquals(15200,r.largest.total);assertEquals(3,r.top.get(0).quantity);assertEquals(22500,r.top.get(0).value);}
