"""Original synthesized alarm motifs. No third-party samples or casino recordings."""
from pathlib import Path
import math, wave, struct, json
ROOT=Path(__file__).resolve().parents[1]/'app/src/main/res/raw'
RATE=32000

def tone(freq,t,duration,kind):
 if t<0 or t>=duration:return 0.
 attack=min(1,t/.006);release=min(1,(duration-t)/.02)
 if kind=='brass':
  env=attack*release*(.8+.2*math.exp(-t*10))
  return env*sum(math.sin(2*math.pi*freq*k*t+.009*math.sin(2*math.pi*5*t))*a for k,a in [(1,.6),(2,.3),(3,.22),(4,.12),(5,.08)])
 if kind=='marimba':
  env=attack*release*math.exp(-t*6)
  return env*(math.sin(2*math.pi*freq*t)+.35*math.sin(2*math.pi*freq*4*t))
 env=attack*release*math.exp(-t*3.8)
 return env*(math.sin(2*math.pi*freq*t)+.45*math.sin(2*math.pi*freq*2.01*t)+.22*math.sin(2*math.pi*freq*3.94*t))

profiles={
 'signature':(2.8,[(0,784,.28,'brass',.8),(.16,784,.25,'brass',.8),(.36,1046.5,.52,'brass',.75),(.36,1568,.65,'bell',.35),(1.20,784,.28,'brass',.8),(1.38,784,.25,'brass',.8),(1.58,1174.7,.58,'brass',.75),(1.58,1568,.7,'bell',.35)]),
 'grand_signal':(2.5,[(0,659.25,.4,'marimba',.75),(.15,987.77,.38,'brass',.65),(.35,1318.5,.5,'brass',.7),(.35,1975.5,.65,'bell',.22),(1.10,659.25,.4,'marimba',.75),(1.26,987.77,.38,'brass',.65),(1.48,1318.5,.64,'brass',.7)]),
 'crystal_call':(2.7,[(0,1046.5,.6,'bell',.75),(.20,1318.5,.6,'bell',.75),(.42,1568,.7,'bell',.65),(.42,784,.48,'brass',.5),(1.22,1046.5,.6,'bell',.75),(1.42,1318.5,.6,'bell',.75),(1.64,1568,.7,'bell',.65),(1.64,784,.55,'brass',.5)])}
report={}
for name,(duration,notes) in profiles.items():
 values=[]
 for i in range(round(RATE*duration)):
  t=i/RATE;value=sum(tone(f,t-at,d,k)*amp for at,f,d,k,amp in notes)
  values.append(math.tanh(1.65*value))
 peak=max(abs(v) for v in values);values=[v*.94/peak for v in values]
 with wave.open(str(ROOT/(name+'.wav')),'wb') as w:
  w.setparams((1,2,RATE,0,'NONE','not compressed'));w.writeframes(b''.join(struct.pack('<h',round(v*32767)) for v in values))
 rms=math.sqrt(sum(v*v for v in values)/len(values));report[name]={'durationSeconds':duration,'peak':round(max(abs(v) for v in values),4),'rms':round(rms,4),'rmsDbfs':round(20*math.log10(rms),2),'clippedSamples':sum(abs(v)>=1 for v in values)}
(ROOT/'order_chime.wav').unlink(missing_ok=True)
print(json.dumps(report,indent=2))
